import csv
import datetime
import json
import os
import sys
from decimal import Decimal


FACT_MAPPING = {
    "offered wage": ("lca_disclosure", "WAGE_RATE_OF_PAY_FROM", "amount"),
    "prevailing wage": ("lca_disclosure", "PREVAILING_WAGE", "amount"),
    "begin date": ("lca_disclosure", "BEGIN_DATE", "date"),
    "end date": ("lca_disclosure", "END_DATE", "date"),
}


def parse_date(val):
    val_str = str(val).strip()
    if not val_str:
        return None
    try:
        serial = float(val_str)
        d = datetime.date(1899, 12, 30) + datetime.timedelta(days=int(round(serial)))
        return d.strftime("%Y-%m-%d")
    except ValueError:
        pass

    for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%d/%m/%Y", "%Y/%m/%d"):
        try:
            d = datetime.datetime.strptime(val_str, fmt).date()
            return d.strftime("%Y-%m-%d")
        except ValueError:
            pass

    return val_str


def parse_amount(val):
    val_str = str(val).strip()
    if not val_str:
        return None
    val_str = val_str.replace("$", "").replace(",", "").strip()
    try:
        d = Decimal(val_str)
        return str(d)
    except Exception:
        return val_str


def load_table(packet_dir, doc_name):
    # Find file matching doc_name.*
    for fname in os.listdir(packet_dir):
        base, _ = os.path.splitext(fname)
        if base.lower() == doc_name.lower():
            fpath = os.path.join(packet_dir, fname)
            rows = []
            with open(fpath, "r", encoding="utf-8", errors="replace") as f:
                reader = csv.DictReader(f)
                for r in reader:
                    clean_row = {
                        k.strip(): v.strip() if v is not None else ""
                        for k, v in r.items()
                        if k is not None
                    }
                    rows.append(clean_row)
            return rows, base
    return [], doc_name


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    pairs = manifest.get("pairs", [])
    facts_spec = manifest.get("facts", {})

    # Cache loaded documents
    loaded_docs = {}

    output = {}

    for pair in pairs:
        if "::" not in pair:
            continue
        rule_id, entity = pair.split("::", 1)
        entity = entity.strip()
        facts_list = facts_spec.get(rule_id, [])

        pair_result = {}

        for fact in facts_list:
            fact_key = fact.strip().lower()
            if fact_key in FACT_MAPPING:
                doc_name, col_name, val_type = FACT_MAPPING[fact_key]
            else:
                doc_name = "lca_disclosure"
                col_name = fact.upper().replace(" ", "_")
                val_type = "text"

            if doc_name not in loaded_docs:
                loaded_docs[doc_name] = load_table(packet_dir, doc_name)

            rows, actual_doc_name = loaded_docs[doc_name]

            # Find matching rows for this entity
            extracted_vals = []
            for r in rows:
                case_no = r.get("CASE_NUMBER", "").strip()
                if case_no == entity:
                    raw_val = r.get(col_name, "").strip()
                    if raw_val != "":
                        if val_type == "date":
                            parsed = parse_date(raw_val)
                        elif val_type == "amount":
                            parsed = parse_amount(raw_val)
                        else:
                            parsed = raw_val
                        if parsed is not None:
                            extracted_vals.append(parsed)

            if len(extracted_vals) == 0:
                pair_result[fact] = "ABSENT"
            else:
                unique_vals = list(dict.fromkeys(extracted_vals))
                if len(unique_vals) > 1:
                    pair_result[fact] = "CONFLICT"
                else:
                    pair_result[fact] = [unique_vals[0], actual_doc_name]

        output[pair] = pair_result

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()
